 static List<string> lines=new List<string>();static string root;static BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;static object Field(object target,string name){return target.GetType().GetField(name,Flags).GetValue(target);}static object Call(object target,string name,params object[] args){return target.GetType().GetMethods(Flags).First(m=>m.DeclaringType==target.GetType()&&m.Name==name&&m.GetParameters().Length==args.Length).Invoke(target,args);}static void Pump(int ms){DateTime end=DateTime.UtcNow.AddMilliseconds(ms);while(DateTime.UtcNow<end){Application.DoEvents();Thread.Sleep(8);}}static void Capture(Form form,string name){Pump(80);using(var bitmap=new Bitmap(form.Width,form.Height)){using(var graphics=Graphics.FromImage(bitmap)){var dc=graphics.GetHdc();try{if(!PrintWindow(form.Handle,dc,2))throw new Exception("Own-window capture failed.");}finally{graphics.ReleaseHdc(dc);}}bitmap.Save(Path.Combine(root,name+".png"));}}static void Assert(bool b,string s){if(!b)throw new Exception(s);}
