 [STAThread]static int Main(string[] args){root=args[0];Directory.CreateDirectory(root);Environment.SetEnvironmentVariable("SLOPSTUDIO_PROFILE",Path.Combine(root,"gui-profile"));Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{var settings=new AppSettings{AudioBackend="WASAPI"};settings.Integration.QuickStart=false;var locale=LocaleCatalog.Load(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"locales","en-US.json"),"en-US");using(var form=new MainForm(settings,locale,false,null)){form.Show();Pump(220);foreach(var display in Screen.AllScreens)lines.Add("DISPLAY "+display.DeviceName+" "+display.Bounds);Assert(form.Visible&&form.Width>=1120,"Main window not usable.");lines.Add("PASS real Windows main window startup; DPI="+GetDpiForWindow(form.Handle)+" size="+form.Size);Call(form,"OpenProjectPath",Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Examples","First Light","First Light.slopdaw"));var project=(ProjectDocument)Field(form,"_project");var first=project.Tracks[0];Call(form,"Select",(Guid?)first.Id,(Guid?)first.Regions[0].Id);Call(form,"ExecuteCommand",AppCommand.ShowSteps);Pump(80);var steps=(Control)Field(form,"_steps");int before=first.Regions[0].Notes.Count;typeof(StepSequencerEditor).GetMethod("OnMouseDown",Flags).Invoke(steps,new object[]{new MouseEventArgs(MouseButtons.Left,1,(int)(98*DisplayScale.For(steps)),(int)(43*DisplayScale.For(steps)),0)});Assert(first.Regions[0].Notes.Count!=before,"Step editor did not change real MIDI.");Capture(form,"steps");lines.Add("PASS step sequencer click changed persisted MIDI note data");
