 Call(form,"ExecuteCommand",AppCommand.TracksOnly);((SplitContainer)Field(form,"_workspaceSplit")).Panel2Collapsed=false;((SplitContainer)Field(form,"_workspaceSplit")).SplitterDistance=(int)(((SplitContainer)Field(form,"_workspaceSplit")).Height*.58);Call(form,"ExecuteCommand",AppCommand.ToggleMixer);Call(form,"ExecuteCommand",AppCommand.ToggleMixer);Capture(form,"arrangement-mixer");Call(form,"ExecuteCommand",AppCommand.ShowSamples);Capture(form,"sample-browser");Call(form,"ExecuteCommand",AppCommand.ShowSamples);
 using(var prefs=new PreferencesForm(settings)){prefs.Show(form);Pump(80);Capture(prefs,"preferences-audio");prefs.Close();}using(var splash=new SplashForm()){splash.Show(form);Capture(splash,"splash");splash.Close();}using(var chooser=new QuickStartForm(new List<RecoveryItem>(),null)){chooser.Show(form);Capture(chooser,"quick-start");chooser.Close();}using(var export=new AudioExportDialog(project)){export.Show(form);Capture(export,"export");export.Close();}
 form.WindowState=FormWindowState.Normal;form.Size=new Size(1280,800);Pump(120);Capture(form,"1280x800");Assert(((Control)Field(form,"_timeline")).Width>300,"Arrangement clipped at 1280x800");byte[] originalKeys=new byte[256];GetKeyboardState(originalKeys);byte[] ctrlKeys=(byte[])originalKeys.Clone();ctrlKeys[0x11]=0x80;ctrlKeys[0x12]=0x80;try{SetKeyboardState(ctrlKeys);var filter=(IMessageFilter)Field(form,"_wheelFilter");var timeline=(TimelineEditor)Field(form,"_timeline");Point pointer=timeline.PointToScreen(new Point(timeline.Width/2,timeline.Height/2));Message wheel=Message.Create(timeline.Handle,0x20a,new IntPtr((120<<16)|8),new IntPtr((pointer.Y<<16)|(pointer.X&65535)));int scaleBefore=settings.UiScale;Assert(filter.PreFilterMessage(ref wheel)&&settings.UiScale==scaleBefore+1,"Ctrl+Alt-wheel did not adjust scale by 1%.");wheel.WParam=new IntPtr((-120<<16)|8);filter.PreFilterMessage(ref wheel);Assert(settings.UiScale==scaleBefore,"Reverse Ctrl+Alt-wheel did not restore scale.");lines.Add("PASS Ctrl+Alt+wheel changes workspace scale by exact 1%; Ctrl+wheel editor zoom covered by V7GuiTests");}finally{SetKeyboardState(originalKeys);}settings.UiScale=125;Call(form,"ApplyUiScale");Capture(form,"workspace125");lines.Add("PASS restored 1280x800 and 125% workspace size; physical per-monitor transition NOT RUN");
