 ((ProjectHistory)Field(form,"_history")).Reset(true);settings.UiScale=100;Call(form,"ApplyUiScale");form.WindowState=FormWindowState.Maximized;Call(form,"CreateLauncherTemplate");Call(form,"ShowSession",1);var sessionProject=(ProjectDocument)Field(form,"_project");Assert(sessionProject.Tracks.Count==4&&sessionProject.Studio.Cells.Count==32,"Launcher template not populated.");Call(form,"StartTransport");Pump(180);Assert(engine.MasterPeak>0,"Starter did not produce real sound.");Capture(form,"launcher-starter");Call(form,"StopAudio");lines.Add("PASS original 4-track / 32-cell launcher starter renders real MIDI through built-in sounds");
 form.GetType().GetField("_closing",Flags).SetValue(form,true);Call(form,"DisposeAdvancedFeatures");engine.Dispose();form.Close();}
